import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Stats and combat responsiveness","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/characters/stats.md","filePath":"game-design/characters/stats.md"}'),o={name:"game-design/characters/stats.md"};function r(s,e,c,l,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="stats-and-combat-responsiveness" tabindex="-1">Stats and combat responsiveness <a class="header-anchor" href="#stats-and-combat-responsiveness" aria-label="Permalink to &quot;Stats and combat responsiveness&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; open questions remain Unresolved. Referenced Accepted decisions retain their existing scope. <strong>Implementation/availability:</strong> no changes to gameplay or runtime configuration; this redesign is not established as live. <strong>Verification:</strong> documentation review, not a playtest; current availability is not established here. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/characters/stats.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/characters/progression.html">Character progression</a></p><h2 id="responsiveness-is-baseline" tabindex="-1">Responsiveness is baseline <a class="header-anchor" href="#responsiveness-is-baseline" aria-label="Permalink to &quot;Responsiveness is baseline&quot;">​</a></h2><p><strong>Stats modify capability; they should not make basic control feel like slow motion.</strong> Low stats must not make an early character feel artificially broken or unusably slow. A new low-DEX character should attack at a believable normal cadence. This is a Proposed experience requirement, not proof that inherited timing has already changed.</p><h2 id="dex-bounded-control-and-recovery" tabindex="-1">DEX: bounded control and recovery <a class="header-anchor" href="#dex-bounded-control-and-recovery" aria-label="Permalink to &quot;DEX: bounded control and recovery&quot;">​</a></h2><p>DEX should not dominate basic swing/animation speed so strongly that low-DEX characters become unusable. Base cadence should primarily reflect weapon class, stance, attack type, recovery, stamina/fatigue, encumbrance and technique. These influences are candidates, not a completed formula or proof that stances/fatigue systems exist.</p><p>Within bounded margins, DEX may influence recovery, aim correction, defensive responsiveness, balance, chained actions and precision under pressure. Magnitudes and stacking are unresolved.</p><h2 id="str-handling-and-physical-capability" tabindex="-1">STR: handling and physical capability <a class="header-anchor" href="#str-handling-and-physical-capability" aria-label="Permalink to &quot;STR: handling and physical capability&quot;">​</a></h2><p>STR should not mean every weapon deals proportionally more damage. Potential roles include heavy-weapon and heavy-armor handling, stamina cost/endurance relationships, grappling/physical contests, control of high-draw bows, reasonable blunt-force potential and load/encumbrance. Weapon design and technique remain primary determinants of weapon behavior. No grappling system, draw-weight formula or armor requirement is finalized.</p><h2 id="int-broader-mental-capability" tabindex="-1">INT: broader mental capability <a class="header-anchor" href="#int-broader-mental-capability" aria-label="Permalink to &quot;INT: broader mental capability&quot;">​</a></h2><p>INT should be reconsidered beyond mana pool size, in the context of <a href="/Syrolands-Public/game-design/magic.html">Magery, Meditation, Concentration, spell knowledge and mental states</a>. Possible influences include cognitive capacity, mental resilience, concentration-related behavior and magical resource efficiency/capacity. This is not a complete INT system, new resource or finalized formula.</p><h2 id="stats-support-skill-identity" tabindex="-1">Stats support skill identity <a class="header-anchor" href="#stats-support-skill-identity" aria-label="Permalink to &quot;Stats support skill identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Intended separation</th></tr></thead><tbody><tr><td>Heavy war hammer</td><td>STR helps handling; Macing, Tactics and weapon design express expertise</td></tr><tr><td>Shooting</td><td>DEX supports recovery/control; Archery and player execution express shooting skill</td></tr><tr><td>Magic</td><td>INT supports mental capability; Magery, Meditation, Concentration and knowledge express magical expertise</td></tr></tbody></table><p>Avoid universal dominant stat multipliers that flatten builds. These examples preserve skill roles without deciding future mandatory skill combinations.</p><h2 id="cadence-attack-opportunities-and-animation" tabindex="-1">Cadence, attack opportunities and animation <a class="header-anchor" href="#cadence-attack-opportunities-and-animation" aria-label="Permalink to &quot;Cadence, attack opportunities and animation&quot;">​</a></h2><p>Future combat/technical work must distinguish:</p><ul><li><strong>Animation responsiveness:</strong> visual feedback and presentation timing.</li><li><strong>Attack recovery:</strong> time and constraints before another action/opportunity.</li><li><strong>Actual attack opportunities:</strong> authoritative occasions to resolve an attack.</li><li><strong>Stamina/fatigue constraints:</strong> resource-related limitations, with formulas open.</li><li><strong>Weapon speed:</strong> family/weapon contribution, not automatically an animation playback rate.</li></ul><p>Faster-looking animation does not grant more attacks. Server timing must never wait for client animation completion, and ordinary combat remains automatic under the existing <a href="/Syrolands-Public/game-design/combat/overview.html">combat foundations</a>.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Example</th></tr></thead><tbody><tr><td>USER INTENT</td><td>Request an attack or technique</td></tr><tr><td>AUTHORITATIVE SERVER STATE</td><td>Validate opportunity, resources, recovery and outcome</td></tr><tr><td>SYNCHRONIZED STATE</td><td>Approved action/outcome and timing information</td></tr><tr><td>CLIENT PRESENTATION</td><td>Responsive input feedback and coherent animation</td></tr></tbody></table><p>No renderer, animation assets, network contracts or combat timers are changed here.</p><h2 id="reconciliation-and-open-questions" tabindex="-1">Reconciliation and open questions <a class="header-anchor" href="#reconciliation-and-open-questions" aria-label="Permalink to &quot;Reconciliation and open questions&quot;">​</a></h2><p>Inherited pre-AOS timing depends on current stamina and weapon speed, with DEX influencing stamina capacity. Calling it simply a raw-DEX swing formula would be inaccurate. The new direction is an experience requirement and an implementation gap; exact changes need separate combat design and gameplay measurement.</p><p>Inherited STR damage scaling, INT/mana coupling, total stat cap, configured per-stat maximum/gain and creation values are not selected Syrolands redesign values. Existing source defaults may be overridden; no runtime configuration was inspected.</p><p>Unresolved: total stat cap and stat ranges; stat gain and locks; exact DEX recovery/control contribution; STR weapon/armor and stamina relationships; INT/mana/Concentration model; fatigue/encumbrance effects; weapon cadence ranges; separation of visual timing and authoritative opportunity; skill-specific exceptions; legacy-character conversion. <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">Skill progression</a> and <a href="/Syrolands-Public/game-design/characters/character-creation.html">creation</a> must be reconciled before implementation. No new stat formula or balance is established.</p><h2 id="active-memory-—-batch-04" tabindex="-1">Active Memory — Batch 04 <a class="header-anchor" href="#active-memory-—-batch-04" aria-label="Permalink to &quot;Active Memory — Batch 04&quot;">​</a></h2><p>The latest <a href="/Syrolands-Public/game-design/magic/memory-and-familiarity.html#int-and-preparation">memory proposal</a> emphasizes INT as cognitive workspace for Active Memory capacity, simultaneous pattern complexity and advanced variants. Simple patterns may cost less memory than heavily modified ones. This strengthens the Proposed direction above without resolving INT versus mana, stat ranges, slots or capacity formulas. Meditation organization and per-pattern Familiarity are distinct contributions, not additional INT multipliers already selected.</p>',27)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
